function placeFree(x,y,b){/* stand just outside the building's nearest door */{const W2=(b.kind=='hosp'?2*BW+RD:BW);let e=null,ed=1e9;for(const q of W0.ents){if(q[0]<b.ox||q[0]>b.ox+W2||q[1]<b.oy||q[1]>b.oy+BH||q[3]>0)continue;const d=Math.hypot(q[0]-x,q[1]-y);if(d<ed){ed=d;e=q}}if(e){x=e[0];y=e[1]+40}}const C=8,X0=b.ox-RD/2,Y0=b.oy-RD/2,W=(b.kind=='hosp'?2*BW+RD:BW)+RD,H=BH+RD,GX=Math.ceil(W/C),GY=Math.ceil(H/C),seen=new Uint8Array(GX*GY),q=[];
 const sx=GX>>1,sy=GY-3;if(blocker(X0+sx*C+4,Y0+sy*C+4,8))return;seen[sy*GX+sx]=1;q.push(sx,sy);let best=null,bd=1e9;
 for(let i=0;i<q.length;i+=2){const cx=q[i],cy=q[i+1],px=X0+cx*C+4,py=Y0+cy*C+4,d=Math.hypot(px-x,py-y);if(d<bd){bd=d;best=[px,py]}
  for(const[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){const X=cx+dx,Y=cy+dy;if(X<0||Y<0||X>=GX||Y>=GY)continue;const k=Y*GX+X;if(seen[k])continue;seen[k]=1;if(!blocker(X0+X*C+4,Y0+Y*C+4,8))q.push(X,Y)}}
 if(best){S.p.x=best[0];S.p.y=best[1]}}
